import{_ as e,o as r,c as a,a0 as o}from"./chunks/framework.akKRIpjQ.js";const p=JSON.parse('{"title":"00 · Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/00-introduction.md","filePath":"guide/00-introduction.md"}'),i={name:"guide/00-introduction.md"};function n(s,t,d,l,h,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="_00-·-introduction" tabindex="-1">00 · Introduction <a class="header-anchor" href="#_00-·-introduction" aria-label="Permalink to &quot;00 · Introduction&quot;">​</a></h1><blockquote><p><strong>AceCrush Craft</strong> — a tennis-equipment data tool. Offline-first, focused on calculation and tracking.</p></blockquote><h2 id="what-problem-does-it-solve" tabindex="-1">What problem does it solve? <a class="header-anchor" href="#what-problem-does-it-solve" aria-label="Permalink to &quot;What problem does it solve?&quot;">​</a></h2><p>After a few years of playing, the bag holds several rackets, a few different tension settings, and you can&#39;t remember &quot;when did I last restring&quot;. Racket specs, overgrip compensation, tension conversion, AI grip measurement — these are all &quot;tooling work&quot; that no one wants to do with ten different webpages or a sprawling Excel file.</p><p>AceCrush Craft is one small App with <strong>four features</strong> that cover the day-to-day:</p><table tabindex="0"><thead><tr><th>#</th><th>Feature</th><th>What it does</th></tr></thead><tbody><tr><td>1</td><td><strong>AI grip size</strong></td><td>Take a photo of your palm → recommended grip size</td></tr><tr><td>2</td><td><strong>Racket profile</strong></td><td>Record each racket&#39;s specs &amp; notes, all on-device</td></tr><tr><td>3</td><td><strong>Stringing log</strong></td><td>One line per restring + reminders</td></tr><tr><td>4</td><td><strong>Tension conversion</strong></td><td>DT / RT / lbs / kg cross-calculator → sends the result straight into the stringing log</td></tr></tbody></table><p>All data is local SQLite, <strong>no upload</strong>.</p><h2 id="supported-platforms" tabindex="-1">Supported platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported platforms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Status</th></tr></thead><tbody><tr><td><strong>Android</strong></td><td>✅ V1.0.x shipped</td></tr><tr><td>iOS</td><td>❌ <strong>Not supported in this version</strong> (planned, no available build)</td></tr><tr><td>Web / Desktop</td><td>❌ Not provided</td></tr></tbody></table><h2 id="version-roadmap" tabindex="-1">Version roadmap <a class="header-anchor" href="#version-roadmap" aria-label="Permalink to &quot;Version roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Status</th><th>Theme</th></tr></thead><tbody><tr><td><strong>V1.0</strong></td><td>✅ Current</td><td>The 4 features above</td></tr></tbody></table><h2 id="three-pillars" tabindex="-1">Three pillars <a class="header-anchor" href="#three-pillars" aria-label="Permalink to &quot;Three pillars&quot;">​</a></h2><h3 id="_1-offline-first" tabindex="-1">1. Offline-first <a class="header-anchor" href="#_1-offline-first" aria-label="Permalink to &quot;1. Offline-first&quot;">​</a></h3><p>Apart from these, <strong>everything works offline</strong>:</p><ul><li><strong>Feedback submission</strong> (only sent when you press &quot;Send&quot;)</li></ul><p>Racket profile, stringing log, grip-measurement results, reminder schedule — <strong>all in the device&#39;s local SQLite</strong>; uninstalling wipes them; nothing is uploaded to any server.</p><h3 id="_2-non-intrusive" tabindex="-1">2. Non-intrusive <a class="header-anchor" href="#_2-non-intrusive" aria-label="Permalink to &quot;2. Non-intrusive&quot;">​</a></h3><ul><li><strong>No push matrix</strong>: notifications fire only for &quot;time to restring&quot; alerts</li><li><strong>No user-account system</strong>: V1.0 is fully no-login</li></ul><h3 id="_3-independently-verifiable" tabindex="-1">3. Independently verifiable <a class="header-anchor" href="#_3-independently-verifiable" aria-label="Permalink to &quot;3. Independently verifiable&quot;">​</a></h3><ul><li>Each calculator&#39;s input &amp; formula is spelled out in the relevant chapter</li><li>The AI grip measurement error budget is given in <a href="./02-grip-size-measurement.html#error-budget-and-mitigations">02 · Grip Size Measurement</a></li><li>All network activity is itemized in <a href="./08-privacy.html">08 · Privacy</a></li></ul><h2 id="the-four-features-—-at-a-glance" tabindex="-1">The four features — at a glance <a class="header-anchor" href="#the-four-features-—-at-a-glance" aria-label="Permalink to &quot;The four features — at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chapter</th><th>What you&#39;ll find</th></tr></thead><tbody><tr><td><a href="./02-grip-size-measurement.html">02 · Grip Size Measurement</a></td><td>Photo → MediaPipe Hand → recommended size (or manual ruler)</td></tr><tr><td><a href="./03-racquets.html">03 · Racket profile</a></td><td>Add / edit / delete rackets and their specs</td></tr><tr><td><a href="./04-stringing-log.html">04 · Stringing log</a></td><td>One record per restring + auto reminder</td></tr><tr><td><a href="./05-tension-conversion.html">05 · Tension conversion</a></td><td>DT ⇄ RT conversion; <strong>tap &quot;Use this tension&quot; → jump straight into the stringing log</strong></td></tr></tbody></table><h2 id="what-v1-0-is-not-doing" tabindex="-1">What V1.0 is <strong>not</strong> doing <a class="header-anchor" href="#what-v1-0-is-not-doing" aria-label="Permalink to &quot;What V1.0 is **not** doing&quot;">​</a></h2><p>To stay focused, these are <strong>out of scope for V1.0</strong>:</p><ul><li>❌ Live video / match recording / community</li><li>❌ Coaching booking / instructor matchmaking / training camps</li><li>❌ In-app store / e-commerce</li><li>❌ Cross-device sync (added in V1.0+; BYO Supabase — see <a href="./06-cloud-sync.html">06 · Cloud Sync</a>)</li><li>❌ Smartwatch / band integrations</li><li>❌ Friends / follows / comments</li></ul><h2 id="reading-paths" tabindex="-1">Reading paths <a class="header-anchor" href="#reading-paths" aria-label="Permalink to &quot;Reading paths&quot;">​</a></h2><ul><li>First contact: <a href="./01-getting-started.html">01 · Getting Started</a> → &quot;add your main racket → record a restring&quot;</li><li>Curious about the AI flow? → <a href="./02-grip-size-measurement.html">02 · Grip Size Measurement</a></li><li>Want to wire tension → stringing in one tap? → <a href="./05-tension-conversion.html">05 · Tension conversion</a> (bottom of page)</li></ul>',27)])])}const g=e(i,[["render",n]]);export{p as __pageData,g as default};
